/**
 * SECURITY VALIDATION TEST
 * Verifies that no real API calls can be made in test environment
 */

import { describe, it, expect, jest, beforeEach } from '@jest/globals';
import OpenAI from 'openai';

describe('Security Mock Validation', () => {
  beforeEach(() => {
    // Clear all mocks before each test
    jest.clearAllMocks();
  });

  it('should mock OpenAI client creation', () => {
    // OpenAI client should be mocked
    const client = new OpenAI({ apiKey: 'test-api-key' });
    expect(client).toBeDefined();
    expect(client.apiKey).toBe('test-api-key');
  });

  it('should prevent real API calls by using mocked responses', async () => {
    const client = new OpenAI({ apiKey: 'test-key' });

    const response = await client.chat.completions.create({
      model: 'gpt-3.5-turbo',
      messages: [{ role: 'user', content: 'test' }],
    });

    // Verify we get mocked response, not real API response
    expect(response).toBeDefined();
    expect(response.id).toBe('mock-completion-id');
    expect(response.choices[0].message.content).toBe('Mock generated content');
    expect(response.choices[0].message.content).not.toContain('real API');
  });

  it('should mock embeddings with deterministic values', async () => {
    const client = new OpenAI({ apiKey: 'test-key' });

    const response = await client.embeddings.create({
      model: 'text-embedding-3-small',
      input: 'test',
    });

    expect(response).toBeDefined();
    expect(response.data).toHaveLength(1);
    expect(response.data[0].embedding).toHaveLength(1536);
    expect(response.data[0].embedding.every(val => typeof val === 'number')).toBe(true);
  });

  it('should block network calls to OpenAI APIs', async () => {
    // Test that fetch is mocked for OpenAI endpoints
    const mockFetch = global.fetch as jest.MockedFunction<typeof fetch>;
    
    // If fetch is mocked, it should prevent real API calls
    if (mockFetch && mockFetch.mock) {
      try {
        await mockFetch('https://api.openai.com/v1/chat/completions');
      } catch (error: any) {
        expect(error.message).toContain('SECURITY');
      }
    } else {
      // If fetch is not mocked, ensure OpenAI is still mocked
      const client = new OpenAI({ apiKey: 'test-key' });
      const response = await client.chat.completions.create({
        model: 'gpt-3.5-turbo',
        messages: [{ role: 'user', content: 'test' }],
      });
      
      // Should get mock response, not real API
      expect(response.id).toBe('mock-completion-id');
    }
  });

  it('should have secure environment configuration', () => {
    // Environment should be configured for testing
    expect(process.env.NODE_ENV).toBe('test');
    
    // Real API keys should not be present or should be test keys
    if (process.env.OPENAI_API_KEY) {
      expect(process.env.OPENAI_API_KEY).toMatch(/^test/);
    }
    
    // Test-specific keys should be set
    if (process.env.TEST_OPENAI_API_KEY) {
      expect(process.env.TEST_OPENAI_API_KEY).toMatch(/^test/);
    }
  });

  it('should track mock calls without making real requests', async () => {
    const client = new OpenAI({ apiKey: 'test-key' });

    // Access the mock function
    const mockCreate = (client.chat.completions.create as jest.MockedFunction<any>);

    // Clear any previous calls
    if (mockCreate.mockClear) {
      mockCreate.mockClear();
    }

    // Make a call
    await client.chat.completions.create({
      model: 'gpt-3.5-turbo',
      messages: [{ role: 'user', content: 'test' }],
    });

    // Verify mock was called (not real API)
    if (mockCreate.mock) {
      expect(mockCreate).toHaveBeenCalledTimes(1);
      expect(mockCreate).toHaveBeenCalledWith({
        model: 'gpt-3.5-turbo',
        messages: [{ role: 'user', content: 'test' }],
      });
    }
  });

  it('should validate that OpenAI responses are mocked', async () => {
    const client = new OpenAI({ apiKey: 'test-key' });

    // Test multiple calls return consistent mock data
    const response1 = await client.chat.completions.create({
      model: 'gpt-3.5-turbo',
      messages: [{ role: 'user', content: 'test1' }],
    });

    const response2 = await client.chat.completions.create({
      model: 'gpt-4',
      messages: [{ role: 'user', content: 'test2' }],
    });

    // Both should return mock data
    expect(response1.id).toBe('mock-completion-id');
    expect(response2.id).toBe('mock-completion-id');
    expect(response1.choices[0].message.content).toBe('Mock generated content');
    expect(response2.choices[0].message.content).toBe('Mock generated content');
  });
});
